  "amocrmChecklist.s3.i2":
    "Callback URL sifatida platformangiz domenini kiriting: https://<domen>/integrations/amocrm/callback",
  "amocrmChecklist.s3.i3": 'To\'liq ("Все") ruxsat bering',
